async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  let accepted = 0;
  let rejected = 0;
  let line = 0;
  let cancelRequired = true;
  let parts = [];

  async function visitLine(text) {
    line++;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      rejected++;
      return true;
    }

    accepted++;
    return (await visitor({ line, value })) !== false;
  }

  try {
    while (true) {
      const { done, value } = await reader.read();
      const text = done
        ? decoder.decode()
        : decoder.decode(value, { stream: true });

      let start = 0;
      let end;

      while ((end = text.indexOf("\n", start)) !== -1) {
        parts.push(text.slice(start, end));
        const content = parts.join("");
        parts = [];

        if (!(await visitLine(content))) {
          cancelRequired = !done;
          return { accepted, rejected, stopped: true };
        }

        start = end + 1;
      }

      if (start < text.length) parts.push(text.slice(start));

      if (done) {
        if (parts.length > 0) {
          const content = parts.join("");
          parts = [];

          if (!(await visitLine(content))) {
            cancelRequired = false;
            return { accepted, rejected, stopped: true };
          }
        }

        cancelRequired = false;
        return { accepted, rejected, stopped: false };
      }
    }
  } finally {
    try {
      if (cancelRequired) await reader.cancel();
    } finally {
      reader.releaseLock();
    }
  }
}
